"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81760"],{47209(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.precedencia_fase.antecessora_fora_do_conjunto_canonico","status":422,"titulo":"C\xf3digo da fase antecessora fora do conjunto can\xf4nico"},"descricao":{"codigo":"uniplus.configuracao.precedencia_fase.antecessora_fora_do_conjunto_canonico","requisitos":["UNI-REQ-0139"],"oQueAconteceu":["O campo `antecessoraCodigo` do cadastro de uma preced\xeancia (`POST /api/configuracao/admin/precedencias-fase`) respeita o formato do c\xf3digo de fase, mas n\xe3o \xe9 um dos catorze c\xf3digos do vocabul\xe1rio fechado de fases do processo seletivo (UNI-REQ-0139). A preced\xeancia s\xf3 liga fases desse vocabul\xe1rio. A lista completa est\xe1 em [c\xf3digo fora do conjunto can\xf4nico das catorze fases](/erros/uniplus.configuracao.fase_canonica.codigo_fora_do_conjunto_canonico).","A recusa vem na lista `errors` da resposta, com `field` igual a `antecessoraCodigo`; a mensagem n\xe3o repete o c\xf3digo recusado. Se o outro c\xf3digo tamb\xe9m tiver problema, a recusa dele vem na mesma resposta, e nada \xe9 gravado."],"comoResolver":["Use um dos catorze c\xf3digos, que v\xeam de `GET /api/configuracao/vocabularios/fases-canonicas`, e envie de novo."],"ondeAparece":["Cadastro de uma preced\xeancia entre fases"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Precedencia fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);